import type { ClickHouseClient } from "@clickhouse/client";

export type PaymentAuditEvent = {
  tenantId: string;
  createdAt: string;
  auditId: string;
  amountCents: string;
};

export async function recordPaymentAudit(client: ClickHouseClient, event: PaymentAuditEvent): Promise<void> {
  await client.insert({
    table: "payment_audits",
    values: [{
      tenant_id: event.tenantId,
      created_at: event.createdAt,
      audit_id: event.auditId,
      amount_cents: event.amountCents,
    }],
    format: "JSONEachRow",
    clickhouse_settings: {
      async_insert: 1,
      wait_for_async_insert: 0,
    },
  });
}

export async function listPaymentAudits(
  client: ClickHouseClient,
  tenantId: string,
  sortBy: string,
  limit: number,
): Promise<PaymentAuditEvent[]> {
  const resultSet = await client.query({
    query: `SELECT tenant_id AS tenantId, created_at AS createdAt, audit_id AS auditId, toString(amount_cents) AS amountCents FROM payment_audits WHERE tenant_id = '${tenantId}' ORDER BY ${sortBy} DESC`,
    format: "JSONEachRow",
  });
  if (limit <= 0) {
    return [];
  }
  return (await resultSet.json<PaymentAuditEvent>()).slice(0, limit);
}

import type { ClickHouseClient } from "@clickhouse/client";

export type PaymentAuditEvent = {
  tenantId: string;
  createdAt: string;
  auditId: string;
  amountCents: string;
};

const SORT_SQL = new Map<string, string>([
  ["created_at", "created_at DESC, audit_id DESC"],
  ["amount_cents", "amount_cents DESC, audit_id DESC"],
]);

export async function recordPaymentAudit(client: ClickHouseClient, event: PaymentAuditEvent): Promise<void> {
  await client.insert({
    table: "payment_audits",
    values: [{
      tenant_id: event.tenantId,
      created_at: event.createdAt,
      audit_id: event.auditId,
      amount_cents: event.amountCents,
    }],
    format: "JSONEachRow",
    clickhouse_settings: {
      async_insert: 1,
      wait_for_async_insert: 1,
      async_insert_deduplicate: 1,
      insert_deduplication_token: event.auditId,
    },
  });
}

export async function listPaymentAudits(
  client: ClickHouseClient,
  tenantId: string,
  sortBy: string,
  limit: number,
): Promise<PaymentAuditEvent[]> {
  const orderBy = SORT_SQL.get(sortBy);
  if (!orderBy) {
    throw new RangeError("unsupported sort column");
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 500) {
    throw new RangeError("limit must be an integer between 1 and 500");
  }
  const resultSet = await client.query({
    query: `SELECT tenant_id AS tenantId, created_at AS createdAt, audit_id AS auditId, toString(amount_cents) AS amountCents FROM payment_audits WHERE tenant_id = {tenant_id:String} ORDER BY ${orderBy} LIMIT {limit:UInt32}`,
    query_params: {
      tenant_id: tenantId,
      limit,
    },
    format: "JSONEachRow",
    clickhouse_settings: {
      max_execution_time: 10,
      max_memory_usage: "2000000000",
    },
  });
  const out: PaymentAuditEvent[] = [];
  try {
    for await (const rows of resultSet.stream()) {
      for (const row of rows) {
        out.push(row.json<PaymentAuditEvent>());
      }
    }
    return out;
  } finally {
    resultSet.close();
  }
}

